# Photographs have a local text fallback when the URL fails to load.
def photo(url,alt=''):
 return '<div class="photo-wrap"><div class="photo-fallback"><span style="font-size:29px">⌂</span><span>UDVAR COLLECTION</span></div><img alt="'+H(alt)+'" loading="lazy" src="'+H(url)+'" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover" onerror="this.style.display=\'none\'"></div>'
def cards(items):
 out=''
 for i,p in enumerate(items):
  out+=f'''<article class="property-card" data-id="{p['id']}" data-type="{p['type']}" data-district="{p['district']}" data-price="{p['price']}" data-rooms="{p['rooms']}" data-size="{p['size']}"><div class="property-img"><a href="#ingatlanok" onclick="openProperty('{p['id']}');return false">{photo(p['images'][0],p['title'])}</a><span class="tag">{H(p['badge'])}</span><button class="save-heart" onclick="saveProp('{p['id']}',this)" aria-label="Ingatlan mentése">♡</button><span class="property-code">{p['id']}</span></div><div class="property-card-content"><div class="property-location">⌖ {H(p['location'])}</div><a class="property-title" href="#ingatlanok" onclick="openProperty('{p['id']}');return false">{H(p['title'])}</a><div class="property-specs"><span>▧ {p['size']} m²</span><span>⌂ {p['rooms']} szoba</span><span>{p['type']}</span></div><div class="property-card-bottom"><div><strong>{fmt(p['price'])}</strong><small>{int(p['price']/p['size']):,} Ft / m²</small></div><button class="circle-arrow" title="Megtekintést kérek" onclick="openBooking('{p['id']}')">↗</button></div></div></article>'''
 return out
