sold=f'''<section class="section sold-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">05 <span class="dash"></span> EREDMÉNYEK / MINTA</div><h2>Az eredmény<br><em>számokban is látszik.</em></h2></div><div class="section-right"><p>Három fiktív ügylet szemlélteti az átlátható ügyletbemutatást.</p></div></div><div class="sold-grid">{''.join(f'<div class="sold-card"><div class="sold-img">{photo(p["images"][0],p["title"])}<span>ELADVA · PÉLDA</span></div><div class="sold-content"><h3>{p["title"]}</h3><span>{p["location"]}</span><div class="sold-numbers"><div><small>IRÁNYÁR</small><strong>{fmt(p["price"])}</strong></div><div><small>PÉLDA VÉTELÁR</small><strong>{fmt(p["price"]*1.015)}</strong></div><div><small>NAP</small><strong>{27+i*4}</strong></div></div></div></div>' for i,p in enumerate(ps[:3]))}</div></div></section>'''
mortgage='''<section class="mortgage-section"><div class="container mortgage-layout"><div class="mortgage-copy"><div class="eyebrow">06 <span class="dash"></span> VÁSÁRLÓKNAK</div><h2>A jó otthon<br><em>jó számokkal</em> kezdődik.</h2><p>Mielőtt beleszeretne valamibe, nézze meg, hogyan fér bele a terveibe.</p><div class="mortgage-callout">A hitelkalkulátor tájékoztató jellegű modell; jogosultságot nem vizsgál.</div><button class="text-link" onclick="openLead('Finanszírozási konzultációt kérek')">Finanszírozási segítség →</button></div><div class="mortgage-box"><div class="mortgage-box-head"><h3>Hitelkalkulátor</h3><span>INDIKATÍV · DEMÓ</span></div><div class="rate-tabs"><button class="active" data-rate="6.4" onclick="setRate(6.4,this)">Piaci hitel <small>6,4% példa</small></button><button data-rate="3" onclick="setRate(3,this)">Támogatott példa <small>3% feltételezés</small></button></div><div class="calc-slider"><div class="slider-label"><span>Vételár</span><strong id="mortgage-price-label">80 M Ft</strong></div><input id="mortgage-price" type="range" min="30" max="150" step="5" value="80" oninput="calcMortgage()"></div><div class="calc-slider"><div class="slider-label"><span>Önerő</span><strong id="mortgage-down-label">20 M Ft</strong></div><input id="mortgage-down" type="range" min="5" max="70" value="20" oninput="calcMortgage()"></div><div class="calc-slider"><div class="slider-label"><span>Futamidő</span><strong id="mortgage-years-label">20 év</strong></div><input id="mortgage-years" type="range" min="5" max="30" step="5" value="20" oninput="calcMortgage()"></div><div class="mortgage-result"><div><span>Becsült havi törlesztőrészlet</span><strong id="mortgage-payment">–</strong></div><div class="mortgage-breakdown"><span id="mortgage-principal">Hitelösszeg: –</span><span id="mortgage-income">Becsült jövedelem: –</span></div></div><p class="form-note">Támogatott hitel jogosultsága, banki feltételek és további költségek nem részei a modellnek.</p></div></div></section>'''
teamhtml=f'''<section id="csapat" class="section team-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">07 <span class="dash"></span> SZEMÉLYES FIGYELEM</div><h2>Ismerős arcok.<br><em>Ismerős utcák.</em></h2></div><div class="section-right"><p>Minden környék mögött egy ember áll, aki érti a részleteket.</p></div></div><div class="team-grid">{team}</div><p class="sample-note">Fiktív szakértőnevek, szerepek és bemutatóportrék.</p></div></section>'''
rest=f'''<section class="testimonial-section"><div class="container testimonial-layout"><div><div class="eyebrow light">AMI IGAZÁN SZÁMÍT</div><h2>Nem négyzetmétereket.<br><em>Bizalmat közvetítünk.</em></h2><span class="testimonial-label">SZEMLÉLTETŐ IDÉZET · DEMÓ</span></div><div class="quote-block"><div class="quote-mark">“</div><blockquote>Végig azt éreztük, hogy valaki érti, milyen fontos döntést hozunk.</blockquote><div class="quote-footer">Fiktív ügyfélvélemény · bemutató</div></div></div></section><section id="gyik" class="section faq-section"><div class="container faq-layout"><div><div class="eyebrow">08 <span class="dash"></span> GYAKORI KÉRDÉSEK</div><h2>Tisztán.<br><em>Félreértések nélkül.</em></h2><p>Megválaszoljuk a legfontosabb kérdéseket.</p></div><div class="faq-items">{faqhtml}</div></div></section><section id="kapcsolat" class="section contact-section"><div class="container contact-layout"><div class="contact-copy"><div class="eyebrow">09 <span class="dash"></span> LÉPJÜNK KAPCSOLATBA</div><h2>Az első lépés<br><em>egyszerű.</em></h2><p>Meséljen a tervéről, és találjuk meg együtt a következő jó lépést.</p><div class="contact-lines"><div>✉ <div><small>DEMÓ E-MAIL</small><span>hello@udvar-demo.hu</span></div></div><div>⌖ <div><small>FIKTÍV IRODA</small><span>Budapest, Szabadság tér 7.</span></div></div></div></div><div class="contact-form"><div class="contact-form-head"><span>ÍRJON NEKÜNK</span><span>DEMÓ · NINCS ADATKÜLDÉS</span></div><form onsubmit="demoSubmit(event,'contact')"><div class="chip-group"><button type="button" class="active">Eladnék</button><button type="button">Vásárolnék</button><button type="button">Értékbecslés</button></div><div class="input-two"><label>Név<input required placeholder="Teljes név"></label><label>Telefon<input required placeholder="+36..."></label></div><label>E-mail<input required type="email" placeholder="E-mail-cím"></label><label>Üzenet<textarea required rows="3" placeholder="Miben segíthetünk?"></textarea></label><label class="consent"><input type="checkbox" required>Elfogadom, hogy az űrlap csupán demó és nem küld adatot.</label><button class="btn btn-primary btn-block">Üzenet küldése · demó →</button></form></div></div></section></main><footer class="footer"><div class="container"><div class="footer-top"><div><div class="eyebrow light">A KÖVETKEZŐ FEJEZET</div><h2>Egy jó döntés<br><em>egy beszélgetéssel</em> kezdődik.</h2></div><a href="#kapcsolat" class="btn btn-primary">Kapcsolatfelvétel ↗</a></div><div class="footer-grid"><div class="footer-about"><a href="#top" class="logo"><span class="logo-mark"><span>U</span></span><span class="logo-word">UDVAR<span>INGATLAN</span></span></a><p>Ingatlanügyletek. Átgondoltan.</p><span>Ez egy fiktív ingatlaniroda felületi bemutatója, minden hirdetés és eredmény szemléltető.</span></div><div><h4>NAVIGÁCIÓ</h4>{navlinks}</div><div><h4>KAPCSOLAT</h4><a href="#kapcsolat">Kapcsolat</a><a href="#ertekbecsles">Értékbecslés</a></div><div><h4>FIGYELEM</h4><span>Az ajánlatok nem valósak. A számítások fiktív adatokat használnak.</span></div></div><div class="footer-bottom"><span>© 2026 UDVAR Ingatlan koncepció</span><span>Nem valós üzleti ajánlat.</span><a href="#top">Vissza a tetejére ↑</a></div></div></footer>'''
modal='''<div class="modal-overlay" id="preview-modal"><div class="modal-card" role="dialog" aria-modal="true"><button class="modal-close" onclick="closeModal()">×</button><div class="modal-kicker" id="preview-modal-kicker">UDVAR / DEMÓ</div><h2 id="preview-modal-title">Kapcsolatfelvétel</h2><p id="preview-modal-info" class="modal-desc">A bemutató nem továbbít valódi adatokat.</p><form onsubmit="demoSubmit(event,'modal')"><label>Név<input required placeholder="Teljes név"></label><label>E-mail<input type="email" required placeholder="E-mail"></label><div id="preview-booking-when" hidden><p class="field-label">Válasszon demó időpontot</p><div class="booking-slots"><button type="button" onclick="this.classList.toggle('selected')">09:00</button><button type="button" onclick="this.classList.toggle('selected')">10:00</button><button type="button" onclick="this.classList.toggle('selected')">14:00</button><button type="button" onclick="this.classList.toggle('selected')">16:00</button></div></div><label class="consent"><input required type="checkbox">Tudomásul veszem, hogy ez egy demó, és nem történik valódi adatküldés.</label><button class="btn btn-primary btn-block">Igény rögzítése · demó →</button></form></div></div><div class="mobile-sticky"><a href="#ertekbecsles">▣ Értékbecslés</a><a href="#ingatlanok">⌕ Ingatlanok</a><a href="#kapcsolat">✉ Kapcsolat</a></div>'''
script='''<script>
const DATA=__DATA__;
const money=n=>Math.round(n).toLocaleString('hu-HU')+' Ft';
const mm=n=>(n/1e6).toLocaleString('hu-HU',{maximumFractionDigits:1})+' M Ft';
let mode='seller',filter='';let saved=[];let vtyp='Lakás',vcond='Jó állapotú',selDistrict=11,rate=6.4;
try{saved=JSON.parse(localStorage.getItem('udvar-saved-preview')||'[]')}catch{}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),2700)}
function heroMode(x){mode=x;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===x));document.getElementById('hero-label').textContent=x==='seller'?'ALAPTERÜLET':'MAXIMÁLIS KERET';document.getElementById('hero-unit').textContent=x==='seller'?'m²':'M Ft';document.getElementById('hero-number').value=x==='seller'?'75':'150';document.getElementById('hero-action-label').textContent=x==='seller'?'Mennyit ér az otthonom?':'Ingatlanok keresése'}
function heroAction(){let dis=document.getElementById('hero-district').value,ty=document.getElementById('hero-type').value,n=Number(document.getElementById('hero-number').value);if(mode==='seller'){if(dis)document.getElementById('value-district').value=dis;if(ty)vType(ty);document.getElementById('value-size').value=n||75;document.getElementById('value-size-label').textContent=(n||75)+' m²';location.hash='ertekbecsles';return}if(dis)document.getElementById('list-district').value=dis;if(ty)filterType(ty,document.querySelector('.filter-switch button:nth-child('+(ty==='Lakás'?2:3)+')'));document.getElementById('preview-extra').hidden=false;document.getElementById('list-budget').value='0';applyFilters();location.hash='ingatlanok'}
function filterType(x,btn){filter=x;document.querySelectorAll('.filter-switch button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');applyFilters()}
function applyFilters(){const dist=document.getElementById('list-district').value,budget=Number(document.getElementById('list-budget').value),rooms=Number(document.getElementById('list-rooms').value);const cards=[...document.querySelectorAll('.property-card')];let count=0;for(const c of cards){let show=(!filter||c.dataset.type===filter)&&(!dist||c.dataset.district===dist)&&(!budget||Number(c.dataset.price)<=budget)&&Number(c.dataset.rooms)>=rooms;c.classList.toggle('card-is-hidden',!show);if(show)count++}const sort=document.getElementById('list-sort').value;cards.sort((a,b)=>sort==='priceAsc'?Number(a.dataset.price)-Number(b.dataset.price):sort==='priceDesc'?Number(b.dataset.price)-Number(a.dataset.price):0);cards.forEach(c=>document.getElementById('preview-properties').append(c));document.getElementById('list-count').textContent=count;document.getElementById('preview-no-results').style.display=count?'none':'block'}
function resetFilters(){filter='';document.getElementById('list-district').value='';document.getElementById('list-budget').value='0';document.getElementById('list-rooms').value='0';filterType('',document.querySelector('.filter-switch button'))}
function saveProp(id,btn){if(saved.includes(id)){saved=saved.filter(x=>x!==id);btn.textContent='♡';toast('Eltávolítva')}else{saved.push(id);btn.textContent='♥';toast('Ingatlan elmentve')}localStorage.setItem('udvar-saved-preview',JSON.stringify(saved));document.getElementById('saved-count').textContent=saved.length}
function showSaved(){let names=DATA.properties.filter(p=>saved.includes(p.id)).map(p=>p.title);toast(names.length?'Mentve: '+names.join(' · '):'Még nincs mentett ingatlan')}
function openModal(k,title,info,booking=false){document.getElementById('preview-modal-kicker').textContent=k;document.getElementById('preview-modal-title').textContent=title;document.getElementById('preview-modal-info').textContent=info;document.getElementById('preview-booking-when').hidden=!booking;document.getElementById('preview-modal').classList.add('show')}
function closeModal(){document.getElementById('preview-modal').classList.remove('show')}
function openBooking(id){const p=DATA.properties.find(x=>x.id===id);openModal('MEGTEKINTÉS · DEMÓ','Találkozzunk a helyszínen.',p.title+' · '+p.location+' — időpontigény demonstráció',true)}
function openLead(ctx){openModal('KAPCSOLAT · DEMÓ','Beszéljünk a részletekről.',ctx,false)}
function openProperty(id){const p=DATA.properties.find(x=>x.id===id);openModal('INGATLAN ADATLAP ELŐNÉZET',p.title,p.location+' · '+p.size+' m² · '+p.rooms+' szoba · '+mm(p.price)+'. A ZIP-ben mind a 10 ingatlanhoz külön, teljes Next.js adatlap tartozik.',true)}
function demoSubmit(e,area){e.preventDefault();e.target.reset();if(area==='modal')closeModal();toast('A demó sikeres állapotot mutat; valódi üzenet nem ment ki.')}
function calcSale(){const sale=Number(document.getElementById('preview-sale').value),cost=Number(document.getElementById('preview-holding').value),a=sale*1e6*.029*1.27,b=sale*1e6*.04*1.27;document.getElementById('preview-sale-label').textContent=sale+' M Ft';document.getElementById('preview-holding-label').textContent=money(cost*1000);document.getElementById('preview-fee').textContent=money(a);document.getElementById('preview-fee-other').textContent=money(b);document.getElementById('preview-saving').textContent=money(b-a);document.getElementById('preview-holding-result').textContent=money(cost*2000);document.getElementById('preview-total').textContent=mm(b-a+cost*2000)}
function vType(t){vtyp=t;document.getElementById('v-lakas').classList.toggle('active',t==='Lakás');document.getElementById('v-haz').classList.toggle('active',t==='Ház')}
function vCondition(b){vcond=b.dataset.cond;document.querySelectorAll('[data-cond]').forEach(x=>x.classList.remove('active'));b.classList.add('active')}
function vStep(n){[1,2,3].forEach(i=>document.getElementById('valuation-step-'+i).hidden=i!==n);document.getElementById('preview-progress-number').textContent='0'+n+' / 03';document.getElementById('preview-progress').style.width=n*100/3+'%';if(n===3){const dist=DATA.districtData.find(d=>d.id===Number(document.getElementById('value-district').value)),sz=Number(document.getElementById('value-size').value),mult={'Felújítandó':.78,'Jó állapotú':1,'Felújított':1.13,'Újszerű':1.2}[vcond],mid=dist.median*sz*mult*(vtyp==='Ház'?.88:1);document.getElementById('preview-estimate').textContent=mm(mid*.94)+' – '+mm(mid*1.06)}}
function setDistrict(id,btn){selDistrict=id;const d=DATA.districtData.find(x=>x.id===id);document.querySelectorAll('.district-tile').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.getElementById('map-name').innerHTML=d.name+' <span>kerület</span>';document.getElementById('map-price').innerHTML=money(d.median)+'<small>mintául vett négyzetméterár</small>';document.getElementById('map-growth').textContent='+'+d.year.toString().replace('.',',')+'%';document.getElementById('map-days').textContent=d.days+' nap';document.getElementById('map-example').textContent=mm(d.median*65)}
function copyDistrict(){document.getElementById('value-district').value=selDistrict}
function searchDistrict(){document.getElementById('list-district').value=selDistrict;applyFilters()}
function setRate(v,b){rate=v;document.querySelectorAll('[data-rate]').forEach(x=>x.classList.toggle('active',x===b));calcMortgage()}
function calcMortgage(){const price=Number(document.getElementById('mortgage-price').value),deposit=Math.min(Number(document.getElementById('mortgage-down').value),price-1),years=Number(document.getElementById('mortgage-years').value);document.getElementById('mortgage-price-label').textContent=price+' M Ft';document.getElementById('mortgage-down-label').textContent=deposit+' M Ft';document.getElementById('mortgage-years-label').textContent=years+' év';const principal=(price-deposit)*1e6,r=rate/1200,n=years*12,pay=principal*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);document.getElementById('mortgage-payment').textContent=money(pay);document.getElementById('mortgage-principal').textContent='Hitelösszeg: '+mm(principal);document.getElementById('mortgage-income').textContent='Példa jövedelmi keret: '+money(pay/.4)}
document.getElementById('saved-count').textContent=saved.length;document.querySelectorAll('.save-heart').forEach(b=>b.textContent=saved.includes(b.closest('.property-card').dataset.id)?'♥':'♡');calcSale();calcMortgage();
</script>'''
script=script.replace('__DATA__',json.dumps(D,ensure_ascii=False).replace('</','<\\/'))
HTML=head+hero+proof+listings+methodhtml+valuation+maphtml+sold+mortgage+teamhtml+rest+modal+script+'</body></html>'
# Fix preview mobile menu style and dynamic toggle
HTML=HTML.replace('class="preview-menu-items"','class="preview-menu-items"')
HTML=HTML.replace('</style>','\n#preview-menu.show{display:flex!important;position:absolute;top:68px;left:0;right:0;background:var(--paper);padding:20px;flex-direction:column;gap:17px;border-bottom:1px solid var(--line)}\n.preview-valuation-output{line-height:1.3}\n</style>',1)
(root/'udvar-preview.html').write_text(HTML)
print('Created standalone preview',len(HTML),'bytes')
